(()=>{
 const q=s=>document.querySelector(s),status=q('#archive-status'),standalone=!!q('[data-archive-page]');let role=null,busy=false,generation=0,offset=0,ownerKey=null,timer=null;
 const states={building:'Создаётся',uploading:'Загружается в Google Drive',verifying:'Проверяется',verified:'Проверен',failed:'Ошибка'};
 async function api(path='',method='GET',data){const response=await fetch('/api/material-archives'+path,{method,cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json','X-Requested-With':'KrugPi'},...(data?{body:JSON.stringify(data)}:{})});const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'Не удалось загрузить архивы.');return result;}
 const el=(tag,value)=>{const node=document.createElement(tag);if(value!==undefined)node.textContent=value;return node};
 function student(){return role==='admin'?Number(q('#student-select').value)||null:null}
 async function refresh(){if(!role)return;const owner=student();if(ownerKey!==owner){offset=0;ownerKey=owner}const token=++generation;clearTimeout(timer);q('#material-archives').hidden=false;q('#archive-create-controls').hidden=role!=='admin';q('#archive-create').disabled=busy||!owner;q('#archive-student-hint').hidden=!!owner;
 try{const params=new URLSearchParams({limit:20,offset});if(owner)params.set('student_id',owner);const result=await api('?'+params);if(token!==generation)return;const list=q('#archive-list');list.replaceChildren();let active=false;
 for(const row of result.items){const entry=el('article');entry.className='archive-entry';const body=el('div');body.append(el('strong',row.filename));body.append(el('p',row.lesson_count+' занятий · '+row.file_count+' файлов'+(row.size?' · '+(row.size/1024/1024).toLocaleString('ru-RU',{maximumFractionDigits:1})+' МБ':'')+' · '+new Date(row.created_at*1000).toLocaleDateString('ru-RU')));const state=el('p',states[row.status]||row.status);if(row.status==='verified')state.className='archive-verified';body.append(state);if(row.error){const error=el('p',row.error);error.className='archive-error';body.append(error)}entry.append(body);if(row.status==='verified'){const link=el('a','Скачать ZIP →');link.href='/api/material-archives/'+encodeURIComponent(row.id)+'/download';entry.append(link)}if(['building','uploading','verifying'].includes(row.status))active=true;list.append(entry)}
 if(!result.items.length)list.append(el('p','Архивов пока нет.'));q('#archive-count').textContent='Всего: '+result.total;q('#archive-previous').disabled=offset===0;q('#archive-next').disabled=offset+20>=result.total;if(active)timer=setTimeout(()=>{if(!document.hidden)void refresh()},5000);
 }catch(error){if(token===generation)status.textContent=error.message}}
 window.refreshMaterialArchives=()=>void refresh();
 q('#archive-create').onclick=async()=>{const owner=student();if(!owner||busy)return;if(!confirm('Создать архив материалов выбранного ученика и загрузить в Google Drive? Исходные файлы останутся на сайте.'))return;busy=true;q('#archive-create').disabled=true;status.textContent='Запускаем создание архива…';try{await api('','POST',{student_id:owner,include_recent:q('#archive-include-recent').checked});status.textContent='Архив создаётся. Можно продолжать работу на сайте.';await refresh()}catch(error){status.textContent=error.message}finally{busy=false;q('#archive-create').disabled=!student()}};
 q('#archive-refresh').onclick=()=>{status.textContent='';void refresh()};q('#archive-previous').onclick=()=>{offset=Math.max(0,offset-20);void refresh()};q('#archive-next').onclick=()=>{offset+=20;void refresh()};document.addEventListener('visibilitychange',()=>{if(!document.hidden)void refresh()});window.addEventListener('pagehide',()=>clearTimeout(timer));
 (async()=>{try{const response=await fetch('/api/auth/me',{cache:'no-store'});if(!response.ok)throw Error('Войдите в личный кабинет, чтобы открыть архивы.');const user=await response.json();if(user.must_change_password){if(standalone)location.replace('account.html');return}if(standalone&&user.role!=='student'){location.replace('materials.html');return}if(!standalone&&user.role==='student'){q('#material-archives').hidden=true;return}role=user.role;if(standalone){window.mountStudentNavigation('archives');q('#status').textContent=''}await refresh()}catch(error){if(standalone)q('#status').textContent=error.message}})();
})();
